def lps(str):
    """Write a function to find the longest palindromic subsequence in the given string."""
    s = str
    n = len(s)
    if n < 2:
        return n

    # dp[j] holds the LPS length of s[i:j + 1] for the current i.
    # `prev` holds the LPS length of s[i + 1:j] (the diagonal value)
    # needed when s[i] == s[j].
    dp = [0] * n
    for i in range(n - 1, -1, -1):
        dp[i] = 1
        prev = 0
        si = s[i]
        for j in range(i + 1, n):
            old = dp[j]
            if si == s[j]:
                dp[j] = prev + 2
            elif dp[j - 1] > dp[j]:
                dp[j] = dp[j - 1]
            prev = old
    return dp[n - 1]
